using System;using System.IO;using System.Collections.Generic;
class QuestRewardsFixturesFG {
 static void Check(bool value,string label){if(!value)throw new InvalidDataException(label);}
 static bool Gold(Offline70QuestDefinitionFG q){for(int i=0;i<q.Rewards.Length;i+=2)if(q.Rewards[i]==0)return true;return false;}
 static void Row(StreamWriter w,string name,Offline70QuestDefinitionFG q,byte level){Offline70QuestBasicRewardFG r=Offline70QuestRewardsFG.Calculate(q,level);w.WriteLine(name+"\t"+q.Id+"\t"+q.MinLevel+"\t"+level+"\t"+(q.IgnoreRewardLevel?1:0)+"\t"+(q.Repeatable?1:0)+"\t"+(q.Difficulty??"")+"\t"+q.GoldMultiple+"\t"+(Gold(q)?1:0)+"\t"+r.Experience+"\t"+r.Gold);}
 static int Main(string[] args){try{if(args.Length!=2)return 2;if(Directory.Exists(args[1]))throw new IOException("Fresh rewards fixture directory required");Directory.CreateDirectory(args[1]);Offline70QuestCatalogFG catalog=Offline70QuestCatalogFG.Load(args[0]);int count=0;using(StreamWriter w=new StreamWriter(Path.Combine(args[1],"vectors.tsv"))){w.WriteLine("Name\tId\tMinimum\tLevel\tIgnore\tRepeat\tDifficulty\tMultiple\tHasGold\tExperience\tGold");foreach(Offline70QuestDefinitionFG q in catalog.Definitions.Values)if(q.Supported){Row(w,"catalog-"+q.Id,q,(byte)q.MinLevel);count++;}
  for(byte level=1;level<=70;level++){Offline70QuestDefinitionFG q=new Offline70QuestDefinitionFG{Id=65500,MinLevel=level,Supported=true,Difficulty="X",GoldMultiple=150,Rewards=new int[]{0,999999}};Row(w,"table-level-"+level,q,level);count++;}
  foreach(byte level in new byte[]{1,7,8,12,13,70})foreach(bool ignore in new bool[]{false,true}){Offline70QuestDefinitionFG q=new Offline70QuestDefinitionFG{Id=65501,MinLevel=1,Supported=true,Difficulty="W",GoldMultiple=150,Rewards=new int[]{0,200},IgnoreRewardLevel=ignore};Row(w,"penalty-"+level+"-"+ignore,q,level);count++;}
  foreach(int multiple in new int[]{0,1,10,100,150}){Offline70QuestDefinitionFG q=new Offline70QuestDefinitionFG{Id=65502,MinLevel=1,Supported=true,Difficulty="?",GoldMultiple=multiple,Rewards=new int[]{0,100}};Row(w,"truncation-"+multiple,q,13);count++;}
  Offline70QuestDefinitionFG repeat=new Offline70QuestDefinitionFG{Id=65503,MinLevel=1,Supported=true,Difficulty="Z",GoldMultiple=100,Rewards=new int[]{0,100},Repeatable=true};Row(w,"repeat-no-experience",repeat,1);count++;
 }
  Offline70QuestBasicRewardFG first=Offline70QuestRewardsFG.Calculate(catalog.Get(101),1),second=Offline70QuestRewardsFG.Calculate(catalog.Get(102),1),hunt=Offline70QuestRewardsFG.Calculate(catalog.Get(103),2),material=Offline70QuestRewardsFG.Calculate(catalog.Get(1146),5);Check(first.Experience==15&&first.Gold==10,"quest101 verified basic table reward");Check(second.Experience==468&&second.Gold==151,"quest102 verified basic table reward");Check(hunt.Experience==863&&hunt.Gold==260,"quest103 verified basic table reward");Check(material.Experience==312&&material.Gold==324,"quest1146 verified basic table reward");
  bool rejected=false;try{Offline70QuestRewardsFG.Calculate(new Offline70QuestDefinitionFG{Supported=true,MinLevel=0},1);}catch(InvalidDataException){rejected=true;}Check(rejected,"minimumlevel0 rejected");
  File.WriteAllText(Path.Combine(args[1],"compiled-report.json"),"{\"allPassed\":true,\"vectorCount\":"+count+",\"quest101\":[15,10],\"quest102\":[468,151],\"quest103\":[863,260],\"quest1146\":[312,324],\"tableIndex\":\"level\"}");Console.WriteLine("PASS compiled basic quest rewards vectors="+count+"; native comparison required");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
